package com.bcsystems.siga.service;

import com.bcsystems.siga.domain.*; import com.bcsystems.siga.domain.en.*; import com.bcsystems.siga.dto.*; import com.bcsystems.siga.exception.NotFoundException; import com.bcsystems.siga.repository.*;
import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;

@Service
public class NominaService {
 private final NominaRepository nominas; private final PersonaRepository personas; private final DeduccionRepository deducciones; private final ComisionRepository comisiones; private final DeduccionFijaRepository fijas; private final PrestamoEmpleadoRepository prestamos; private final AsistenciaRepository asistencias;
 public NominaService(NominaRepository n,PersonaRepository p,DeduccionRepository d,ComisionRepository c,DeduccionFijaRepository f,PrestamoEmpleadoRepository pr,AsistenciaRepository a){nominas=n;personas=p;deducciones=d;comisiones=c;fijas=f;prestamos=pr;asistencias=a;}
 private Persona persona(Integer id){return personas.findById(id).orElseThrow(()->new NotFoundException("Persona no encontrada"));}
 private void periodo(LocalDate i,LocalDate f,LocalDate pago){if(i==null||f==null||i.getDayOfWeek()!=DayOfWeek.FRIDAY||f.getDayOfWeek()!=DayOfWeek.THURSDAY||!f.equals(i.plusDays(6))||pago==null||pago.isBefore(f.plusDays(1)))throw new IllegalArgumentException("La nómina debe cubrir de viernes a jueves y pagarse a partir del viernes siguiente");}
 private boolean dentro(LocalDate d,LocalDate i,LocalDate f){return d!=null&&!d.isBefore(i)&&!d.isAfter(f);}
 private void generarAutomaticos(Persona p,LocalDate i,LocalDate f){
  BigDecimal hora=p.getSueldoHora()!=null?p.getSueldoHora():(p.getSueldoSemanal()==null?BigDecimal.ZERO:p.getSueldoSemanal().divide(BigDecimal.valueOf(48),4,RoundingMode.HALF_UP));
  asistencias.findByPersonaIdPersonaOrderByFechaDesc(p.getIdPersona()).stream().filter(a->!a.getFecha().isBefore(i)&&!a.getFecha().isAfter(f)).forEach(a->{
   if(a.getMinutosRetardo()!=null&&a.getMinutosRetardo()>0&&!deducciones.existsByPersonaIdPersonaAndFechaAndTipo(p.getIdPersona(),a.getFecha(),TipoDeduccion.RETARDO)) crearDeduccion(p,"Retardo ("+a.getMinutosRetardo()+" min)",hora.multiply(BigDecimal.valueOf(a.getMinutosRetardo())).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP),a.getFecha(),TipoDeduccion.RETARDO,OrigenDeduccion.ASISTENCIA);
   if(a.getMinutosSalidaTemprana()!=null&&a.getMinutosSalidaTemprana()>0&&!deducciones.existsByPersonaIdPersonaAndFechaAndTipo(p.getIdPersona(),a.getFecha(),TipoDeduccion.SALIDA_TEMPRANA)) crearDeduccion(p,"Salida temprana ("+a.getMinutosSalidaTemprana()+" min)",hora.multiply(BigDecimal.valueOf(a.getMinutosSalidaTemprana())).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP),a.getFecha(),TipoDeduccion.SALIDA_TEMPRANA,OrigenDeduccion.ASISTENCIA);
  });
  prestamos.findByPersonaIdPersonaAndEstado(p.getIdPersona(),EstadoPrestamo.ACTIVO).forEach(pr->pr.getParcialidades().forEach(x->{if((x.getEstado()==EstadoParcialidad.PENDIENTE||x.getEstado()==EstadoParcialidad.VENCIDA)&&!x.getFechaVencimiento().isAfter(f)&&!deducciones.existsByPrestamoParcialidadIdParcialidad(x.getIdParcialidad())) deducciones.save(Deduccion.builder().persona(p).concepto("Parcialidad de préstamo "+pr.getIdPrestamo()+" #"+x.getNumero()).monto(x.getMonto()).fecha(x.getFechaVencimiento()).estado(EstadoDeduccion.PENDIENTE).tipo(TipoDeduccion.PRESTAMO).origen(OrigenDeduccion.PRESTAMO).prestamoParcialidad(x).build());}));
  fijas.findAll().stream().filter(x->Boolean.TRUE.equals(x.getActivo())&&!x.getFechaInicio().isAfter(f)&&(x.getFechaFin()==null||!x.getFechaFin().isBefore(i))&&x.getPersonas().contains(p)).forEach(x->{if(deducciones.findByDeduccionFijaIdDeduccionFijaAndPersonaIdPersonaAndPeriodoInicioAndPeriodoFin(x.getIdDeduccionFija(),p.getIdPersona(),i,f).isEmpty())deducciones.save(Deduccion.builder().persona(p).concepto(x.getConcepto()).monto(x.getMonto()).fecha(f).periodoInicio(i).periodoFin(f).estado(EstadoDeduccion.PENDIENTE).tipo(TipoDeduccion.FIJA).origen(OrigenDeduccion.FIJA).deduccionFija(x).build());});
 }
 private Deduccion crearDeduccion(Persona p,String c,BigDecimal m,LocalDate f,TipoDeduccion t,OrigenDeduccion o){return deducciones.save(Deduccion.builder().persona(p).concepto(c).monto(m).fecha(f).estado(EstadoDeduccion.PENDIENTE).tipo(t).origen(o).build());}
 private List<Comision> conceptosCom(Persona p,LocalDate i,LocalDate f){return comisiones.findByPersonaIdPersonaAndEstadoComision(p.getIdPersona(),EstadoComision.PENDIENTE).stream().filter(x->dentro(x.getFechaComision(),i,f)&&x.getNomina()==null).toList();}
 private List<Deduccion> conceptosDed(Persona p,LocalDate i,LocalDate f){return deducciones.findByPersonaIdPersonaAndEstadoIn(p.getIdPersona(),List.of(EstadoDeduccion.PENDIENTE,EstadoDeduccion.APROBADA)).stream().filter(x->dentro(x.getFecha(),i,f)&&x.getNomina()==null).toList();}
 private void totales(Nomina n,List<Comision> cs,List<Deduccion> ds){BigDecimal c=cs.stream().map(Comision::getMontoComision).reduce(BigDecimal.ZERO,BigDecimal::add),d=ds.stream().map(Deduccion::getMonto).reduce(BigDecimal.ZERO,BigDecimal::add);n.setTotalComisiones(c);n.setTotalDeducciones(d);n.setSueldo(n.getSueldoBase().add(c).subtract(d));}
 private NominaResponse response(Nomina n){return NominaResponse.of(n);}
 @Transactional public NominaBatchResponse preparar(NominaBatchRequest r){periodo(r.fechaInicio(),r.fechaFin(),r.fechaPago());List<Nomina> list=new ArrayList<>();personas.findAll().stream().filter(p->Boolean.TRUE.equals(p.getActiva())).forEach(p->{generarAutomaticos(p,r.fechaInicio(),r.fechaFin());Nomina n=nominas.findByPersonaIdPersonaAndFechaInicioAndFechaFin(p.getIdPersona(),r.fechaInicio(),r.fechaFin()).orElseGet(()->nominas.save(Nomina.builder().persona(p).fechaNomina(r.fechaPago()).fechaInicio(r.fechaInicio()).fechaFin(r.fechaFin()).sueldoBase(nvl(p.getSueldoSemanal())).totalComisiones(BigDecimal.ZERO).totalDeducciones(BigDecimal.ZERO).sueldo(nvl(p.getSueldoSemanal())).estado(EstadoNomina.PENDIENTE_REVISION).build()));if(n.getEstado()==EstadoNomina.PENDIENTE_REVISION)totales(n,conceptosCom(p,r.fechaInicio(),r.fechaFin()),conceptosDed(p,r.fechaInicio(),r.fechaFin()));list.add(nominas.save(n));});return resumen(list);}
 private BigDecimal nvl(BigDecimal x){return x==null?BigDecimal.ZERO:x;}
 private NominaBatchResponse resumen(List<Nomina> ns){return new NominaBatchResponse(ns.stream().map(this::response).toList(),ns.stream().map(Nomina::getSueldoBase).reduce(BigDecimal.ZERO,BigDecimal::add),ns.stream().map(Nomina::getTotalComisiones).reduce(BigDecimal.ZERO,BigDecimal::add),ns.stream().map(Nomina::getTotalDeducciones).reduce(BigDecimal.ZERO,BigDecimal::add),ns.stream().map(Nomina::getSueldo).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @Transactional public NominaResponse revisar(Long id,NominaReviewRequest r){Nomina n=nominas.findById(id).orElseThrow(()->new NotFoundException("Nómina no encontrada"));if(n.getEstado()!=EstadoNomina.PENDIENTE_REVISION&&n.getEstado()!=EstadoNomina.REVISADA)throw new IllegalArgumentException("La nómina no está disponible para revisión");List<Comision> cs=comisiones.findAllById(r==null||r.comisionIds()==null?List.of():r.comisionIds());List<Deduccion> ds=deducciones.findAllById(r==null||r.deduccionIds()==null?List.of():r.deduccionIds());if(cs.stream().anyMatch(x->!x.getPersona().getIdPersona().equals(n.getPersona().getIdPersona())||x.getNomina()!=null||x.getEstadoComision()!=EstadoComision.PENDIENTE||!dentro(x.getFechaComision(),n.getFechaInicio(),n.getFechaFin()))||ds.stream().anyMatch(x->!x.getPersona().getIdPersona().equals(n.getPersona().getIdPersona())||x.getNomina()!=null||x.getEstado()==EstadoDeduccion.RECHAZADA||!dentro(x.getFecha(),n.getFechaInicio(),n.getFechaFin())))throw new IllegalArgumentException("Hay conceptos inválidos para esta nómina");cs.forEach(x->{x.setNomina(n);comisiones.save(x);});ds.forEach(x->{if(x.getEstado()==EstadoDeduccion.PENDIENTE&&x.getOrigen()==OrigenDeduccion.ASISTENCIA)x.setEstado(EstadoDeduccion.APROBADA);x.setNomina(n);deducciones.save(x);});totales(n,cs,ds);n.setEstado(EstadoNomina.REVISADA);return response(nominas.save(n));}
 @Transactional public NominaBatchResponse generar(List<Long> ids){if(ids==null||ids.isEmpty())throw new IllegalArgumentException("Selecciona al menos una nómina revisada");List<Nomina> ns=nominas.findAllById(ids);if(ns.size()!=new HashSet<>(ids).size()||ns.stream().anyMatch(x->x.getEstado()!=EstadoNomina.REVISADA))throw new IllegalArgumentException("Todas las nóminas deben estar revisadas");ns.forEach(n->{List<Comision> cs=comisiones.findByNominaIdNomina(n.getIdNomina());List<Deduccion> ds=deducciones.findByNominaIdNomina(n.getIdNomina());totales(n,cs,ds);cs.forEach(x->{x.setEstadoComision(EstadoComision.PAGADA);x.setFechaPago(n.getFechaNomina());comisiones.save(x);});ds.forEach(x->{x.setEstado(EstadoDeduccion.APLICADA);if(x.getPrestamoParcialidad()!=null){x.getPrestamoParcialidad().setEstado(EstadoParcialidad.PAGADA);}deducciones.save(x);});n.setEstado(EstadoNomina.GENERADA);nominas.save(n);});return resumen(ns);}
 @Transactional public NominaResponse cancelar(Long id){Nomina n=nominas.findById(id).orElseThrow(()->new NotFoundException("Nómina no encontrada"));if(n.getEstado()==EstadoNomina.CANCELADA)throw new IllegalArgumentException("La nómina ya está cancelada");comisiones.findByNominaIdNomina(id).forEach(x->{x.setNomina(null);x.setEstadoComision(EstadoComision.PENDIENTE);x.setFechaPago(null);comisiones.save(x);});deducciones.findByNominaIdNomina(id).forEach(x->{x.setNomina(null);x.setEstado(EstadoDeduccion.PENDIENTE);if(x.getPrestamoParcialidad()!=null)x.getPrestamoParcialidad().setEstado(EstadoParcialidad.PENDIENTE);deducciones.save(x);});n.setEstado(EstadoNomina.CANCELADA);return response(nominas.save(n));}
 public List<NominaResponse> listar(){return nominas.findAll().stream().sorted(Comparator.comparing(Nomina::getIdNomina).reversed()).map(this::response).toList();}
 public NominaDesgloseResponse desglose(Integer id,LocalDate i,LocalDate f){Persona p=persona(id);generarAutomaticos(p,i,f);List<ConceptoResponse> cs=conceptosCom(p,i,f).stream().map(x->new ConceptoResponse(x.getIdComision(),x.getConcepto(),x.getMontoComision(),x.getFechaComision(),x.getEstadoComision().name(),"COMISION")).toList();List<ConceptoResponse> ds=conceptosDed(p,i,f).stream().map(x->new ConceptoResponse(x.getIdDeduccion(),x.getConcepto(),x.getMonto(),x.getFecha(),x.getEstado().name(),x.getOrigen().name())).toList();return new NominaDesgloseResponse(id,p.getNombre()+" "+p.getApellido(),nvl(p.getSueldoSemanal()),cs,ds,cs.stream().map(ConceptoResponse::monto).reduce(BigDecimal.ZERO,BigDecimal::add),ds.stream().map(ConceptoResponse::monto).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @Transactional public Deduccion crearDeduccion(DeduccionRequest r){Persona p=persona(r.personaId());return crearDeduccion(p,r.concepto(),r.monto(),r.fecha()==null?LocalDate.now():r.fecha(),TipoDeduccion.MANUAL,OrigenDeduccion.MANUAL);}
 public List<Deduccion> listarDeducciones(){return deducciones.findAll();}
 @Transactional public Comision crearComision(ComisionRequest r){Persona p=persona(r.personaId());BigDecimal m=r.monto()!=null?r.monto():r.montoBase().multiply(r.porcentaje()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);return comisiones.save(Comision.builder().persona(p).concepto(r.concepto()).montoBase(r.montoBase()).porcentajeComision(r.porcentaje()).montoComision(m).tipoComision(r.tipo()==null?TipoComision.MANUAL:r.tipo()).estadoComision(EstadoComision.PENDIENTE).fechaComision(r.fecha()==null?LocalDate.now():r.fecha()).build());}
 public List<Comision> listarComisiones(){return comisiones.findAll();}
 @Transactional public PrestamoEmpleado crearPrestamo(PrestamoRequest r){Persona p=persona(r.personaId());if(r.montoPrincipal()==null||r.numeroParcialidades()==null||r.numeroParcialidades()<1)throw new IllegalArgumentException("Datos de préstamo inválidos");PrestamoEmpleado x=PrestamoEmpleado.builder().persona(p).montoPrincipal(r.montoPrincipal()).tasaInteresPorcentaje(nvl(r.tasaInteresPorcentaje())).numeroParcialidades(r.numeroParcialidades()).fechaPrimerPago(r.fechaPrimerPago()==null?LocalDate.now().plusWeeks(1):r.fechaPrimerPago()).fechaCreacion(LocalDateTime.now()).estado(EstadoPrestamo.ACTIVO).build();BigDecimal pago=x.getMontoPrincipal().add(x.getMontoPrincipal().multiply(x.getTasaInteresPorcentaje()).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP)).divide(BigDecimal.valueOf(x.getNumeroParcialidades()),2,RoundingMode.HALF_UP);for(int i=1;i<=x.getNumeroParcialidades();i++)x.getParcialidades().add(PrestamoParcialidad.builder().prestamo(x).numero(i).capital(x.getMontoPrincipal().divide(BigDecimal.valueOf(x.getNumeroParcialidades()),2,RoundingMode.HALF_UP)).interes(BigDecimal.ZERO).monto(pago).saldo(x.getMontoPrincipal().subtract(x.getMontoPrincipal().divide(BigDecimal.valueOf(x.getNumeroParcialidades()),2,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(i))).max(BigDecimal.ZERO)).fechaVencimiento(x.getFechaPrimerPago().plusWeeks(i-1L)).estado(EstadoParcialidad.PENDIENTE).build());return prestamos.save(x);}
 public List<PrestamoEmpleado> listarPrestamos(){return prestamos.findAll();}
 @Transactional public DeduccionFija crearFija(DeduccionFijaRequest r){DeduccionFija x=DeduccionFija.builder().concepto(r.concepto()).monto(r.monto()).activo(r.activo()==null||r.activo()).fechaInicio(r.fechaInicio()).fechaFin(r.fechaFin()).personas((r.personaIds()==null?List.<Integer>of():r.personaIds()).stream().map(this::persona).collect(Collectors.toSet())).build();return fijas.save(x);}
 public List<DeduccionFija> listarFijas(){return fijas.findAll();}
 public NominaDesgloseResponse desgloseNomina(Long id){Nomina n=nominas.findById(id).orElseThrow(()->new NotFoundException("Nómina no encontrada"));List<ConceptoResponse> cs=comisiones.findByNominaIdNomina(id).stream().map(x->new ConceptoResponse(x.getIdComision(),x.getConcepto(),x.getMontoComision(),x.getFechaComision(),x.getEstadoComision().name(),"COMISION")).toList();List<ConceptoResponse> ds=deducciones.findByNominaIdNomina(id).stream().map(x->new ConceptoResponse(x.getIdDeduccion(),x.getConcepto(),x.getMonto(),x.getFecha(),x.getEstado().name(),x.getOrigen().name())).toList();return new NominaDesgloseResponse(n.getPersona().getIdPersona(),n.getPersona().getNombre()+" "+n.getPersona().getApellido(),n.getSueldoBase(),cs,ds,n.getTotalComisiones(),n.getTotalDeducciones());}
}
